registerRoute(
  new NavigationRoute(
    new NetworkFirst({ cacheName: "pages", networkTimeoutSeconds: 3, plugins: [expiration()] }),
    { denylist: NETWORK_ONLY },
  ),
);

/** The app shell for a navigation nothing else answered; the router renders the route offline. */
const shell = createHandlerBoundToURL(APP_SHELL);
setCatchHandler(async (options) => {
  if (options.request.mode !== "navigate") return Response.error();
  try {
    return await shell(options);
  } catch {
    return (await matchPrecache(OFFLINE_FALLBACK)) ?? Response.error();
  }
});

// offline.backgroundSync: true → drains the outbox
