self.addEventListener("push", handlePush); // push.enabled: true; in-app elsewhere
self.addEventListener("pushsubscriptionchange", handlePushSubscriptionChange);
self.addEventListener("notificationclick", handleNotificationClick);
// updates.strategy: prompt, skipWaitingOnAccept
self.addEventListener("message", handleSkipWaiting);
